	"sort"
	"strings"
	"sync"
	"testing"

	"github.com/entireio/entire-graph/internal/sem"
)

var (
	probeMu   sync.Mutex
	probeSets = map[string]map[[16]byte]int{}
)

func probeGroup(name string) string {
	if i := strings.Index(name, "/"); i >= 0 {
		name = name[:i]
	}
	for _, g := range []string{"AnchorsOnTheSignature", "NeverDropsVerify", "NonExactQueriesAreByteIdentical", "NeverLocatesLess"} {
		if strings.Contains(name, g) {
			return g
		}
	}
	return "other"
}

func probeRecord(t *testing.T, response sem.SearchResponse, budget int, exactName bool) {
	g := probeGroup(t.Name())
	if g == "other" {
		return
	}
	raw, err := json.Marshal(response)
	if err != nil {
		panic(err)
	}
	h := sha256.New()
	h.Write(raw)
	var b [9]byte
	binary.LittleEndian.PutUint64(b[:8], uint64(budget))
	if exactName {
		b[8] = 1
	}
	h.Write(b[:])
	var k [16]byte
	copy(k[:], h.Sum(nil))
	probeMu.Lock()
	if probeSets[g] == nil {
		probeSets[g] = map[[16]byte]int{}
	}
	probeSets[g][k]++
	probeMu.Unlock()
}

func TestMain(m *testing.M) {
	code := m.Run()
	if out := os.Getenv("PROBE_OUT"); out != "" {
		var sb strings.Builder
		groups := make([]string, 0, len(probeSets))
		for g := range probeSets {
			groups = append(groups, g)
		}
		sort.Strings(groups)
		for _, g := range groups {
			set := probeSets[g]
			keys := make([]string, 0, len(set))
			calls := 0
			for k, n := range set {
				keys = append(keys, string(k[:]))
				calls += n
			}
			sort.Strings(keys)
			h := sha256.New()
			for _, k := range keys {
				h.Write([]byte(k))
			}
			fmt.Fprintf(&sb, "%s distinct=%d calls=%d digest=%x\n", g, len(set), calls, h.Sum(nil)[:8])
		}
		_ = os.WriteFile(out, []byte(sb.String()), 0o644)
	}
	os.Exit(code)
}

